// Extract vehicle + contact data
const vehicle = $('Get Vehicle from Zoho CRM1').item.json.data[0];
const contact = $('Get Contact from Zoho CRM1').item.json.data[0];

// Field values
const kennzeichenValue = vehicle.Kennzeichen || vehicle.Kennzeichen_1 || vehicle.Name || '';
const hersteller = vehicle.Hersteller || '';
const modell = vehicle.Modell || '';

// Build personalized form URL
const formBase = 'https://forms.zohopublic.com/warihaasimgm1/form/Fahrzeugdaten/formperma/TsA_gd8q3ENa5ERZKM1TgL47fWqfkvHzRoBr49wjjw8';

const vehicleId = vehicle.id;
const kennzeichen = encodeURIComponent(kennzeichenValue);
const fahrzeug = encodeURIComponent((hersteller + ' ' + modell).trim());
const fahrzeugtyp = encodeURIComponent(vehicle.Fahrzeugtyp || '');

const formUrl = `${formBase}?FahrzeugID=${vehicleId}&Kennzeichen=${kennzeichen}&Fahrzeug=${fahrzeug}&Fahrzeugtyp=${fahrzeugtyp}`;

// Contact data
const contactName = (contact.First_Name || '') + ' ' + (contact.Last_Name || '');
const contactEmail = contact.Email;

if (!contactEmail) {
  throw new Error(`Kein Email für Kontakt ${contactName} (ID: ${contact.id}) – Datensatz übersprungen.`);
}

const emailSubject = `Fahrzeugdaten benötigt – ${kennzeichenValue}`;

const emailBody = `Sehr geehrte/r ${contactName},

für Ihr Fahrzeug (${hersteller} ${modell}, Kennzeichen: ${kennzeichenValue}) benötigen wir einige aktualisierte Angaben für Ihre Versicherungsakte.

Bitte nehmen Sie sich kurz Zeit und füllen Sie das folgende Formular aus:

${formUrl}

Dies dauert nur etwa 2 Minuten. Ihre persönlichen Daten sowie Fahrzeugdetails sind bereits vorausgefüllt — Sie müssen nur die fehlenden Informationen ergänzen.

Bei Fragen stehen wir Ihnen jederzeit zur Verfügung.

Mit freundlichen Grüßen
Ihr Versicherungsteam`;

// Zoho v3 API requires strict ISO 8601 string format
// Example: 2026-09-08T02:37:12Z
const now = new Date();
const zohoDateTime = now.toISOString();

return [{
  json: {
    vehicleId,
    vehicleName: `${hersteller} ${modell}`,
    kennzeichen: kennzeichenValue,
    contactName,
    contactEmail,
    formUrl,
    emailSubject,
    emailBody,
    currentTime: zohoDateTime
  }
}];

