// Parse form submission from Zoho Forms webhook
const body = $input.item.json.body || $input.item.json;

// Automatic search: Poore data mein se 19-digit waali Zoho ID dhoondna
let vehicleId = "";
for (const key in body) {
  const value = String(body[key]).trim();
  // Zoho ID hamesha 19 characters ki sirf ek ginti (number) hoti hai
  if (/^\d{19}$/.test(value)) {
    vehicleId = value;
    break;
  }
}

// Agar automatic search fail ho jaye toh purane tareeqe par fallback karna
if (!vehicleId) {
  vehicleId = body.FahrzeugID || body.SingleLine || body.SingleLine1 || "";
}

// Baki 5 fields ka data nikalna
const jahresfahrleistung = body.Jahresfahrleistung || body.Dropdown || "";
const kilometerstand = body.Kilometerstand || body.Number || "0";
const stellplatz = body.Stellplatz || body.Dropdown1 || "";
const nutzung = body.Nutzung || body.Dropdown2 || "";
const selbstbeteiligung = body.Selbstbeteiligung || body.Number1 || "0";

if (!vehicleId) {
  throw new Error('FahrzeugID fehlt in der Formularantwort – Datensatz kann nicht zugeordnet werden.');
}

return [{
  json: {
    vehicleId,
    jahresfahrleistung,
    kilometerstand: parseInt(kilometerstand) || 0,
    stellplatz,
    nutzung,
    selbstbeteiligung: parseFloat(selbstbeteiligung) || 0,
    submittedAt: new Date().toISOString()
  }
}];

